// `din2` behind `din` in the same cycle. The caller guarantees room for it (level + the first
// push < DEPTH); it is not qualified here. DUAL_PUSH = 0 is the MVP FIFO: the same statements
// as before, so that the MVP netlist does not change.

module pio_fifo #(
    parameter int DEPTH = 4,
    parameter bit DUAL_PUSH = 1'b0,
    localparam int LW = $clog2(DEPTH + 1),
    localparam int PW = $clog2(DEPTH)
) (
    input  logic          clk,
    input  logic          rst_n,
    input  logic          push,
    input  logic [31:0]   din,
    input  logic          push2,
    input  logic [31:0]   din2,
    input  logic          pop,
    output logic [31:0]   head,
    output logic [LW-1:0] level
);
  localparam bit POW2 = (DEPTH & (DEPTH - 1)) == 0;

  logic [31:0] mem[DEPTH];
  logic [PW-1:0] wp, rp;
  logic do_push, do_pop;

  // pointer + 1, wrapping at DEPTH (a plain increment when DEPTH is a power of two)
  function automatic logic [PW-1:0] inc(input logic [PW-1:0] p);
    if (POW2 || p != PW'(DEPTH - 1)) inc = p + PW'(1);
    else inc = '0;
  endfunction

  assign do_push = push && (level != LW'(DEPTH));
  assign do_pop  = pop && (level != '0);
  assign head    = mem[rp];

  if (!DUAL_PUSH) begin : g_single
    always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        for (int i = 0; i < DEPTH; i++) mem[i] <= '0;
        wp    <= '0;
        rp    <= '0;
        level <= '0;
      end else begin
        if (do_push) begin
`ifdef FUZZ_PLANT_RTL7
        // PLANT 7: docs/mvp-isa.md `### Host-to-engine timing` -- a word the
        // host pushes lands at the write pointer and comes out at the read pointer. This stores it
        // one slot along instead: the level is right, and so is everything that leaves the FIFO
        // while the queue does not wrap, because nothing reads the slot it went to. Only a
        // compare of the FIFO storage (lockstep.py --deep, `eng0.tx[i]`) sees it, and
        // `gen.fifofill()` is the run it is caught in.
        mem[inc(wp)] <= din;
`else
        mem[wp] <= din;
`endif
        wp      <= inc(wp);
        end
        if (do_pop) rp <= inc(rp);
        if (do_push && !do_pop) level <= level + LW'(1);
        else if (do_pop && !do_push) level <= level - LW'(1);
      end
    end

    logic unused_p2;
    assign unused_p2 = ^{push2, din2};
  end else begin : g_dual
    logic [PW-1:0] wp1;
    assign wp1 = inc(wp);

    always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        for (int i = 0; i < DEPTH; i++) mem[i] <= '0;
        wp    <= '0;
        rp    <= '0;
        level <= '0;
      end else begin
        if (do_push) begin
          mem[wp] <= din;
          wp      <= wp1;
        end
        if (push2) begin
          // the second word lands behind the first when there was one
          mem[do_push ? wp1 : wp] <= din2;
          wp                      <= do_push ? inc(wp1) : wp1;
        end
        if (do_pop) rp <= inc(rp);
        level <= level + LW'(do_push) + LW'(push2) - LW'(do_pop);
      end
    end
  end
endmodule
